    372 => {
      "...Mate, do you have tomatoes on your ears?" => "...Kumpel, hast du Watte in den Ohren?",
      "...What now? You don't believe that it's just a floor mat?" => "...Was denn noch? Glaubst du etwa nicht, dass das bloß eine Fußmatte ist?",
      "Buddy, I REALLY REALLY don't got anything else for you." => "Kumpel, ich hab WIRKLICH WIRKLICH nichts mehr für dich.",
      "Do you like that, huh?" => "Na, gefällt dir das?",
      "Don't you have anything else to do? Saving the world or something?" => "Hast du nichts Besseres zu tun? Die Welt retten oder so?",
      "Get out of my sight." => "Geh mir aus den Augen.",
      "Here, are you happy now?" => "Hier, bist du jetzt zufrieden?",
      "It seems like you are more annoying than the Donphan down in the circus." => "Du bist ja noch nerviger als das Donphan unten im Zirkus.",
      "Leave." => "Verlassen.",
      "Now PLEASE!" => "Und jetzt BITTE!",
      "Now go." => "Jetzt geh schon.",
      "Okay, how about I just ignore you?" => "Okay, wie wär's, wenn ich dich einfach ignoriere?",
      "There is nothing there, and if so, I just wouldn't give it to anyone for free." => "Da ist nichts. Und selbst wenn, würde ich es nicht einfach verschenken.",
      "We're DONE here." => "Wir sind hier FERTIG.",
    },
    381 => {
      "Lokix challenges you!" => "Lextremo fordert dich heraus!",
      "Lokix glares at you boredly." => "Lextremo mustert dich gelangweilt.",
      "Lokix isn't interested in associating with you." => "Lextremo will nichts mit dir zu tun haben.",
      "Lokix senses the Silver Ring." => "Lextremo spürt den Silberring.",
      "Overqwil challenges you!" => "Myriador fordert dich heraus!",
      "Overqwil glares at you boredly." => "Myriador mustert dich gelangweilt.",
      "Overqwil isn't interested in associating with you." => "Myriador will nichts mit dir zu tun haben.",
      "Overqwil senses the Silver Ring." => "Myriador spürt den Silberring.",
    },
    382 => {
      "Murkrow doesn't seem to respond to anything you do." => "Kramurx reagiert auf nichts, was du tust.",
      "Murkrow is looking at you keenly." => "Kramurx sieht dich aufmerksam an.",
      "Murkrow notices the Silver Ring!" => "Kramurx bemerkt den Silberring!",
      "Murkrow seems obedient. Do you want to take it with you?" => "Kramurx scheint dir gehorchen zu wollen. Willst du es mitnehmen?",
      "Sneasel doesn't seem to respond to anything you do." => "Sniebel reagiert auf nichts, was du tust.",
      "Sneasel is looking at you keenly." => "Sniebel sieht dich aufmerksam an.",
      "Sneasel notices the Silver Ring!" => "Sniebel bemerkt den Silberring!",
      "Sneasel seems obedient. Do you want to take it with you?" => "Sniebel scheint dir gehorchen zu wollen. Willst du es mitnehmen?",
    },
    383 => {
      "Glimmet appears to be vacantly staring at the wall." => "Lumispross starrt geistesabwesend die Wand an.",
      "Glimmet noticed the Silver Ring!" => "Lumispross hat den Silberring bemerkt!",
      "Glimmet seems obedient. Do you want to take it with you?" => "Lumispross scheint dir gehorchen zu wollen. Willst du es mitnehmen?",
      "Salandit appears to be vacantly staring at the wall." => "Molunk starrt geistesabwesend die Wand an.",
      "Salandit noticed the Silver Ring!" => "Molunk hat den Silberring bemerkt!",
