  module Lookup
    def loadMessageFile(filename)
      @local_german_enabled = false
      @local_german_indexes = {}
      result = super
      @local_german_enabled = !!result && File.basename(filename.to_s.tr('\\', '/')).downcase == 'german.dat'
      result
    end

    def getFromHash(type, text)
      result = super(type, text.is_a?(String) && text.frozen? ? text.dup : text)
      return result unless @local_german_enabled
      source = LocalGermanText.key(text)
      if type == MessageTypes::TrainerNames && source
        return LocalGermanText::TRAINER_NAMES[source] || result
      end
      return result unless type == MessageTypes::ScriptTexts
      source = LocalGermanText.key(text)
      return result unless source && LocalGermanText.key(result) == source
      # Existing German translations take precedence over this supplement.
      local_german_lookup(@messages[type], source) || LocalGermanText::SCRIPT_TEXTS[source] || result
    end

    def getFromMapHash(type, text)
      result = super(type, text.is_a?(String) && text.frozen? ? text.dup : text)
      return result unless @local_german_enabled
      source = LocalGermanText.key(text)
      repairs = LocalGermanText::MAP_REPAIRS[type]
      return repairs[source] if repairs && repairs[source]
      return result unless source && LocalGermanText.key(result) == source
      additions = LocalGermanText::MAP_TEXTS[type]
      translated = additions && additions[source]
      maps = @messages && @messages[0]
      common = LocalGermanText::MAP_TEXTS[0]
      translated || (maps && local_german_lookup(maps[type], source)) ||
        (common && common[source]) || (maps && local_german_lookup(maps[0], source)) || result
    end

    private

    def local_german_lookup(table, source)
      return nil unless table.is_a?(Hash)
      @local_german_indexes ||= {}
      cached = @local_german_indexes[table.object_id]
      unless cached && cached[0].equal?(table) && cached[1] == table.size
        index = {}
        table.each do |english, german|
          canonical = LocalGermanText.key(english)
          next unless canonical && german.is_a?(String)
          next if LocalGermanText.key(german) == canonical
          # Do not guess if two whitespace variants have different meanings.
          if index.key?(canonical) && index[canonical] != german
            index[canonical] = nil
          else
            index[canonical] = german
          end
        end
        cached = [table, table.size, index]
        @local_german_indexes[table.object_id] = cached
      end
      cached[2][source]
    end
  end
end

# These option descriptions bypass _INTL in upstream. Translate their display
# value only; preserve callback descriptions and every option's get/set logic.
module LocalGermanText::OptionDescription
  def description
    value = super
    value.is_a?(String) ? _INTL(value) : value
  end
end
[:EnumOption, :NumberOption].each do |name|
  next unless Object.const_defined?(name)
  klass = Object.const_get(name)
  if klass.method_defined?(:description) && !klass.ancestors.include?(LocalGermanText::OptionDescription)
    klass.prepend(LocalGermanText::OptionDescription)
  end
end

# Glamazon already separates menu identifiers from visible labels. Keep those
# identifiers untouched, including future upstream options.
module LocalGermanText::GlamazonLabels
  def swm_GlamazonShop_show_menu(title, items)
    super(title.is_a?(String) ? _INTL(title) : title, items)
  end

  def swm_GlamazonShop_menu_options(*items)
    identifiers, labels = super
    [identifiers, labels.map { |label| label.is_a?(String) ? _INTL(label) : label }]
  end
end
if defined?(Swm_GlamazonShop_PC) && Swm_GlamazonShop_PC.method_defined?(:swm_GlamazonShop_menu_options)
  Swm_GlamazonShop_PC.prepend(LocalGermanText::GlamazonLabels) unless Swm_GlamazonShop_PC.ancestors.include?(LocalGermanText::GlamazonLabels)
end

# Only attach to the existing localization API; do not replace game methods.
module LocalGermanText::FieldNoteNames
  def text
    value = super
    return value unless MessageTypes.class_variable_get(:@@messages).instance_variable_get(:@local_german_enabled)
    value == 'Die Genauigkeit von Cold Snap <icon=fieldChange> <c=green>100</c> ' ?
      'Die Genauigkeit von Kälteschock <icon=fieldChange> <c=green>100</c> ' : value
  end

  def elaboration
    value = super
    return value unless MessageTypes.class_variable_get(:@@messages).instance_variable_get(:@local_german_enabled)
    value == 'Blizzard, Cold Snap, Eisesodem, Eissturm, Polarorkan' ?
      'Blizzard, Kälteschock, Eisesodem, Eissturm, Polarorkan' : value
  end
end
if defined?(PBFieldNote) && PBFieldNote.method_defined?(:text) && PBFieldNote.method_defined?(:elaboration)
  PBFieldNote.prepend(LocalGermanText::FieldNoteNames) unless PBFieldNote.ancestors.include?(LocalGermanText::FieldNoteNames)
end

if defined?(Messages) && defined?(MessageTypes::ScriptTexts) &&
   [:loadMessageFile, :getFromHash, :getFromMapHash].all? { |name| Messages.method_defined?(name) }
  Messages.prepend(LocalGermanText::Lookup) unless Messages.ancestors.include?(LocalGermanText::Lookup)
end

