    "Yellow Street" => ["Yellow-Straße", "Yellow-Strasse", "Yellow Straße", "Yellow Strasse", "Gelbe Straße", "Gelbe Strasse", "Gelben Straße", "Gelben Strasse"],
  }.freeze

  def self.preserve_street_names(source, value)
    source = key(source)
    return value unless source && source.include?('Street') && value.is_a?(String)
    result = value.dup
    result.force_encoding(Encoding::UTF_8) if result.encoding == Encoding::ASCII_8BIT
    return value unless result.valid_encoding?
    source.scan(/(?<!\w)(\d+)(st|nd|rd|th) Street\b/).each do |number, ordinal|
      result.gsub!(/(?<!\w)#{Regexp.escape(number)}\.?\s*(?:Straße|Strasse)(?!\w)/i, number + ordinal + ' Street')
    end
    STREET_ALIASES.each do |english, aliases|
      next unless source.match?(/(?<!\w)#{Regexp.escape(english)}(?!\w)/)
      aliases.each { |name| result.gsub!(/(?<!\w)#{Regexp.escape(name)}(?!\w)/i, english) }
    end
    result == value ? value : result
  end

  module StreetNames
    def getFromHash(type, text)
      value = super
      @local_german_enabled ? LocalGermanText.preserve_street_names(text, value) : value
    end

    def getFromMapHash(type, text)
      value = super
      @local_german_enabled ? LocalGermanText.preserve_street_names(text, value) : value
    end
  end
end
if defined?(Messages) && Messages.ancestors.include?(LocalGermanText::Lookup)
  Messages.prepend(LocalGermanText::StreetNames) unless Messages.ancestors.include?(LocalGermanText::StreetNames)
end
# END ORIGINAL STREET NAMES

