  module CustomEeveeDisplay
    def local_german_eevee_text
      return nil unless LocalGermanVisible.enabled?
      rows = LocalGermanVisible::CUSTOM_EEVEE_TEXTS[@species]
      rows && rows.find { |row| row[:aliases].include?(@name) }
    end

    def name
      row = local_german_eevee_text
      row ? row[:name] : super
    end

    def kind
      row = local_german_eevee_text
      row ? row[:kind] : super
    end

    def dexentry
      row = local_german_eevee_text
      row ? row[:dexentry] : super
    end
  end

  def self.enabled?
    return false unless defined?(MessageTypes) && MessageTypes.class_variable_defined?(:@@messages)
    MessageTypes.class_variable_get(:@@messages).instance_variable_get(:@local_german_enabled) == true
  end

  def self.text(value)
    return value unless value.is_a?(String) && enabled?
    # Direct event/script display calls still belong to their active map. Reuse
    # the engine's current-map/common-map lookup without searching other maps.
    if defined?($game_map) && $game_map && $game_map.respond_to?(:map_id)
      map_id = $game_map.map_id
      if map_id.is_a?(Integer) && map_id > 0
        localized = MessageTypes.getFromMapHash(map_id, value)
        return localized if localized.is_a?(String) && localized != value
      end
    end
    translated = _INTL(value)
    return translated unless translated == value
    TEMPLATES.each do |pattern, template, numbers|
      match = pattern.match(value)
      next unless match
      # Substitute captures once, without interpreting escapes or placeholder-like
      # text inside player/Pokémon names or remote diagnostic messages.
      captures = {}
      numbers.each_with_index { |number, index| captures[number] = match[index + 1] }
      return _INTL(template).gsub(/\{(\d+)\}/) { captures.fetch($1.to_i, $&) }
    end
    value
  end

  def self.commands(values)
    return values unless values.is_a?(Array) && enabled?
    values.map { |value| text(value) }
  end

  module Lookup
    def getFromHash(type, source)
      result = super
      return result unless @local_german_enabled && type == MessageTypes::ScriptTexts
      # The noun in the Pokédex form selector was translated as the verb "bilden".
      # Correct only that known bad translation; retain future upstream wording.
      return 'Form' if LocalGermanText.key(source) == 'Form' && LocalGermanText.key(result) == 'Bilden'
      if Thread.current[:local_german_dex_search]
        compact = LocalGermanVisible::DEX_SEARCH_TEXTS[LocalGermanText.key(source)]
        return compact if compact
      end
      return result unless LocalGermanText.key(result) == LocalGermanText.key(source)
      LocalGermanVisible::TEXTS[LocalGermanText.key(source)] || result
    end
  end

  module Messages
    def pbMessage(message, commands = nil, *args, **kwargs, &block)
      super(LocalGermanVisible.text(message), LocalGermanVisible.commands(commands), *args, **kwargs, &block)
    end

    def pbMessageDisplay(window, message, *args, **kwargs, &block)
      super(window, LocalGermanVisible.text(message), *args, **kwargs, &block)
    end

    def pbShowCommands(window, commands = nil, *args, **kwargs, &block)
      super(window, LocalGermanVisible.commands(commands), *args, **kwargs, &block)
    end

    def pbShowCommandsWithHelp(window, commands, help, *args, **kwargs, &block)
      super(window, LocalGermanVisible.commands(commands), LocalGermanVisible.commands(help), *args, **kwargs, &block)
    end
  end

  module Drawing
    def pbDrawTextPositions(bitmap, positions)
      return super unless LocalGermanVisible.enabled?
      # Only the two fixed labels in the confirmed 512x384 entry layout.
      if Thread.current[:local_german_dex_entry] && bitmap.width == 512 && bitmap.height == 384
        labels, other = positions.partition { |row| row[1] == 318 && [158, 190].include?(row[2]) && [ _INTL('HT'), _INTL('WT') ].include?(row[0]) }
        unless labels.empty?
          result = super(bitmap, other)
          old_font = bitmap.font.clone
          begin
            # Widen the label cells to the left; retain the original skin and value columns.
            skin = AnimatedBitmap.new(_INTL("Graphics/Pictures/Pokedex/pokedexEntry"))
            begin
              bitmap.blt(280, 156, skin.bitmap, Rect.new(304, 156, 4, 66))
              bitmap.stretch_blt(Rect.new(284, 156, 64, 66), skin.bitmap, Rect.new(308, 156, 36, 66))
            ensure
              skin.dispose
            end
            pbSetSystemFont(bitmap)
            labels.each do |row|
              label = row[2] == 158 ? 'GR.' : 'GEW.'
              pbDrawShadowText(bitmap, 286, row[2], 60, 32, label, row[4], row[5], 1)
            end
          ensure
            bitmap.font = old_font
          end
          return result
        end
      end
      localized = positions.map do |position|
        next position unless position.is_a?(Array)
        row = position.dup
        row[0] = LocalGermanVisible.text(row[0])
        if Thread.current[:local_german_pokegear] && row[0] == _INTL('Region Map')
          row[0] = 'Karte'
        end
        if Thread.current[:local_german_weather_date]
          row[0] = LocalGermanVisible.weather_date(row[0])
        end
        row
      end
      super(bitmap, localized)
    end
  end

