  def self.victory_groups(lines)
    groups = []
    lines.each do |line|
      if groups.empty? || line.match?(/\A\s*\d+\./)
        groups << [line]
      else
        groups.last << line
      end
    end
    groups
  end

  def self.victory_lines(lines, bitmap, width)
    victory_groups(lines).flat_map do |original|
      source = LocalGermanText.key(original.map(&:strip).join(' '))
      translated = VICTORY_CLUES[source]
      next original unless translated
      wrapped = []
      line = ''
      translated.split.each do |word|
        candidate = line.empty? ? word : line + ' ' + word
        if !line.empty? && bitmap.text_size(candidate).width > width
          wrapped << line
          line = '   ' + word
        else
          line = candidate
        end
      end
      wrapped << line unless line.empty?
      wrapped
    end
  end

  module VictoryPuzzle
    def pbVictoryRoadPuzzle(number)
      return super unless LocalGermanVisible.enabled?
      LocalGermanVisible.with_layout_context(:local_german_victory_clues) { super }
    end

    def pbListWindow(commands, width = 256)
      window = super
      if LocalGermanVisible.enabled? && Thread.current[:local_german_victory_clues] &&
         commands.is_a?(Array) && commands.all? { |line| line.is_a?(String) }
        window.commands = LocalGermanVisible.victory_lines(commands, window.contents, window.contents.width - 32)
      end
      window
    end
  end

  WEEKDAYS = {'Sun' => 'So', 'Mon' => 'Mo', 'Tue' => 'Di', 'Wed' => 'Mi', 'Thu' => 'Do', 'Fri' => 'Fr', 'Sat' => 'Sa'}.freeze
  MONTHS = {'Jan' => 'Jan', 'Feb' => 'Feb', 'Mar' => 'Mär', 'Apr' => 'Apr', 'May' => 'Mai', 'Jun' => 'Jun', 'Jul' => 'Jul', 'Aug' => 'Aug', 'Sep' => 'Sep', 'Oct' => 'Okt', 'Nov' => 'Nov', 'Dec' => 'Dez'}.freeze
  DAY_PERIODS = {'Day' => 'Tag', 'Night' => 'Nacht', 'Evening' => 'Abend', 'Morning' => 'Morgen'}.freeze

  def self.weather_date(value)
    return value unless value.is_a?(String)
    match = /\A(Sun|Mon|Tue|Wed|Thu|Fri|Sat) +(\d{1,2}) +(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) +- +(Day|Night|Evening|Morning)\z/.match(value)
    return value unless match
    "#{WEEKDAYS[match[1]]}, #{match[2].to_i}. #{MONTHS[match[3]]} - #{DAY_PERIODS[match[4]]}"
  end

  # Keep upstream time/calendar calculations and every update unchanged. Only
  # its exact date-display row is localized while this method draws the panel.
  module WeatherDate
    def pbTimeText
      return super unless LocalGermanVisible.enabled?
      previous = Thread.current[:local_german_weather_date]
      begin
        Thread.current[:local_german_weather_date] = true
        super
      ensure
        Thread.current[:local_german_weather_date] = previous
      end
    end
  end

  # Designed artwork is always loaded unchanged by the upstream cache.
