    887 => {
      'ZERO: The path connects further ahead, I think.' => ['NULL: Der Weg führt weiter nach vorne, denke ich.', 'ZERO: Der Weg führt weiter nach vorne, denke ich.'],
      'ZERO: ...Ah, \\PN.' => ['NULL: ... Ah, \\PN.', 'ZERO: ... Ah, \\PN.'],
      'ZERO: ...' => ['NULL: ...', 'ZERO: ...'],
