    888 => {
      'ZERO: No problem. I\'m here to help.' => ['NULL: Kein Problem. Ich bin hier, um zu helfen.', 'ZERO: Kein Problem. Ich bin hier, um zu helfen.'],
      'ZERO: ...' => ['NULL: ...', 'ZERO: ...'],
