    404 => {
      'That rail hurts.' => ['Diese Schiene tut weh.', 'Die Reling hat ganz schön wehgetan.'],
      'We\'re solid, but give me a minute.' => ['Wir sind solide, aber gib mir eine Minute.', 'Uns geht\'s gut, aber gib mir eine Minute.'],
      'CAIN: I\'ll have to show you some time~' => ['CAIN: Ich muss dir etwas Zeit zeigen~', 'CAIN: Das muss ich dir irgendwann mal zeigen~'],
      'HARDY: Aye. Let\'s stay close and move quickly.' => ['HARDY: Ja. Bleiben wir in der Nähe und handeln wir schnell.', 'HARDY: Ja. Bleiben wir dicht zusammen und gehen zügig weiter.'],
      'CAIN: \\PN, take care of Aya for me, will you?' => ['CAIN: \\PN, kümmern Sie sich für mich um Aya, ja?', 'CAIN: \\PN, kümmer dich für mich um Aya, ja?'],
      'HARDY: \'Course you can.' => ['HARDY: Natürlich können Sie das.', 'HARDY: Klar kannst du das.'],
      'Take care of \\PN for me.' => ['Kümmere dich um \\PN für mich.', 'Pass für mich auf \\PN auf.'],
      'CAIN: Catch up with us as soon as you can!' => ['CAIN: Treffen Sie uns so schnell wie möglich!', 'CAIN: Hol uns so schnell du kannst ein!'],
      'And don\'t worry--' => ['Und keine Sorge –', 'Und mach dir keine Sorgen …'],
      'I\'ll be gentle with your boyfriend~' => ['Ich werde sanft zu deinem Freund sein~', 'Ich pass ganz vorsichtig auf deinen Freund auf~'],
      'So I\'m with you, huh?' => ['Also bin ich bei dir, oder?', 'Also bin ich jetzt mit dir unterwegs, hm?'],
      'How about you just stay away from Calcenon City? That\'s best for everyone!' => ['Wie wäre es, wenn Sie sich einfach von Calcenon City fernhalten? Das ist das Beste für alle!', 'Wie wär\'s, wenn du dich einfach von Calcenon fernhältst? Das ist für alle das Beste!'],
      'Tch, don\'t say I didn\'t warn you~' => ['Tch, sagen Sie nicht, ich hätte Sie nicht gewarnt', 'Tss, sag nicht, ich hätte dich nicht gewarnt~'],
      'Hmph. After the PULSE, are you?' => ['Hmpf. Sind Sie nach dem Pulse?', 'Hmpf. Du suchst also den PULSE?'],
    },
    406 => {
      'Look who showed up!' => ['Schauen Sie, wer aufgetaucht ist!', 'Na, wer ist denn da!'],
      'Hey, grunt!' => ['Hey, grunz!', 'Hey, Rekrut!'],
      'ECLIPSE: Great, do it.' => ['ECLIPSE: Großartig, machen Sie es.', 'ECLIPSE: Na dann, mach schon.'],
      'ECLIPSE: I don\'t think you know what I mean at all.' => ['ECLIPSE: Ich glaube, Sie wissen überhaupt nicht, was ich meine.', 'ECLIPSE: Ich glaube, du verstehst überhaupt nicht, was ich meine.'],
      'I\'m quitting.' => ['Ich gebe auf.', 'Ich steige aus.'],
      'So thanks for wandering in.' => ['Vielen Dank für Ihren Besuch.', 'Also, danke, dass ihr euch hierher verirrt habt.'],
      'ASTER: Eclipse, what the hell do you think you\'re doing?' => ['ASTER: Eclipse, was zur Hölle denkst du, was du tust?', 'ASTER: Eclipse, was zur Hölle soll das?'],
      'ECLIPSE: I literally just said like three different times.' => ['ECLIPSE: Ich habe es im wahrsten Sinne des Wortes dreimal gesagt.', 'ECLIPSE: Das habe ich doch schon dreimal gesagt.'],
      'If one of the Clawitzer\'s attacks hits his house, that\'s it.' => ['Wenn einer der Angriffe des Clawitzers sein Haus trifft, ist es das.', 'Wenn eine von Krebutacks Attacken sein Haus trifft, ist alles vorbei.'],
      'ASTER: Eclipse!' => ['ASTER: Finsternis!', 'ASTER: Eclipse!'],
      'Chandelure\'s flames burn away the soul.' => ['Kronleuchters Flammen verbrennen die Seele.', 'Skelabras Flammen verbrennen die Seele.'],
      'Let\'s move.' => ['Lass uns umziehen.', 'Los, gehen wir.'],
    },
