    [8, 'Bewerbung bei Silph Co. Zwei Jahre Management-Erfahrung oder Abschluss erforderlich.'] => ['Bewerbung bei Silph Co. Zwei Jahre Management-Erfahrung oder Abschluss erforderlich.', 'Bewerbung bei Silph Co. Mind. 2 Jahre Managementerfahrung oder passender Abschluss.'],
    [8, 'Bewerbung bei Sweet Co. Gesucht: offene, energiegeladene Person mit Verkaufserfahrung.'] => ['Bewerbung bei Sweet Co. Gesucht: offene, energiegeladene Person mit Verkaufserfahrung.', 'Bewerbung bei Sweet Co. Offen und voller Energie; Verkaufserfahrung erwünscht.'],
    [8, 'Bewerbung beim Lapis Luxus-Fahrradladen. Gepflegtes Auftreten und Business Casual nötig.'] => ['Bewerbung beim Lapis Luxus-Fahrradladen. Gepflegtes Auftreten und Business Casual nötig.', 'Bewerbung beim Lapis-Luxus-Fahrradladen. Gepflegtes Auftreten und leger-elegante Kleidung.'],
    [8, 'Bewerbung für Kritischen Fang. Voraussetzung: Grundkenntnisse der Pokéball-Technologie.'] => ['Bewerbung für Kritischen Fang. Voraussetzung: Grundkenntnisse der Pokéball-Technologie.', 'Bewerbung bei Critical Capture. Solide Kenntnisse der Pokéball-Technologie erforderlich.'],
    [8, 'Bewerbung für The Spyce. Voraussetzungen: Leidenschaft für alle Speisen und Wissensdurst.'] => ['Bewerbung für The Spyce. Voraussetzungen: Leidenschaft für alle Speisen und Wissensdurst.', 'Bewerbung für The Spyce. Voraussetzungen: Leidenschaft für gutes Essen und Wissensdurst.'],
    [8, 'Bewerbung für den Achat-Zirkus. Voraussetzung: Armdrücken gegen Samson. Sieg nicht erwartet.'] => ['Bewerbung für den Achat-Zirkus. Voraussetzung: Armdrücken gegen Samson. Sieg nicht erwartet.', 'Bewerbung für den Agate-Zirkus. Voraussetzung: Armdrücken gegen Samson. Ein Sieg wird nicht erwartet.'],
    [8, 'Bewerbung für den Medizinmarkt. Voraussetzungen: Kenntnisse in Kräuter- und Chemiebehandlungen.'] => ['Bewerbung für den Medizinmarkt. Voraussetzungen: Kenntnisse in Kräuter- und Chemiebehandlungen.', 'Medizinmarkt-Bewerbung. Erfordert Kenntnisse in Kräuterheilkunde und chemischer Behandlung.'],
    [8, 'Bewerbung für den Reborn Nightclub. Voraussetzungen: Frag DJ Arclight.'] => ['Bewerbung für den Reborn Nightclub. Voraussetzungen: Frag DJ Arclight.', 'Bewerbung für den Reborn-Nachtclub. Voraussetzung: DJ Arclight fragen.'],
    [8, 'Bewerbung für den Städtebau. Voraussetzungen: Schutzhelm und zäher Geist!'] => ['Bewerbung für den Städtebau. Voraussetzungen: Schutzhelm und zäher Geist!', 'Bewerbung im Bauwesen. Voraussetzungen: Schutzhelm und ein zäher Geist!'],
    [8, 'Bewerbung für die Apophyll-Akademie. Voraussetzungen: Keine. Alle Interessierten sind willkommen!'] => ['Bewerbung für die Apophyll-Akademie. Voraussetzungen: Keine. Alle Interessierten sind willkommen!', 'Bewerbung für die Apophyll-Akademie. Es gibt keine Voraussetzungen; alle Interessierten sind willkommen!'],
    [8, 'Blätter vom Kopf eines verstorbenen Knofensa. Manche Fanatiker nutzen sie zur Heilung von Krankheiten.'] => ['Blätter vom Kopf eines verstorbenen Knofensa. Manche Fanatiker nutzen sie zur Heilung von Krankheiten.', 'Blätter vom Kopf eines verstorbenen Myrapla. Manche Fanatiker nutzen sie zur Heilung von Krankheiten.'],
    [8, 'Das Etikett ist mit Wachsmalstift kaum leserlich beschrieben. Es stellt 103 KP eines Pokémon wieder her.'] => ['Das Etikett ist mit Wachsmalstift kaum leserlich beschrieben. Es stellt 103 KP eines Pokémon wieder her.', 'Das Etikett ist mit Wachsmalstift kaum leserlich beschriftet. Das Getränk stellt 103 KP eines Pokémon wieder her.'],
    [8, 'Daten aus einer geheimnisvollen Zelle gewonnen. Einsatz erhöht das natürliche Potenzial eines Pokémon.'] => ['Daten aus einer geheimnisvollen Zelle gewonnen. Einsatz erhöht das natürliche Potenzial eines Pokémon.', 'Daten einer geheimnisvollen Zelle. Steigern das natürliche Potenzial eines Pokémon.'],
    [8, 'Der Träger befreit sich von Bewegungsfesseln und kann sich frei bewegen. Nur einmal verwendbar.'] => ['Der Träger befreit sich von Bewegungsfesseln und kann sich frei bewegen. Nur einmal verwendbar.', 'Einmalig gegen Anziehung, Verhöhner, Zugabe, Folterknecht, Aussetzer und Heilblockade.'],
    [8, 'Der beruhigende Kliklak dieser Glocke beruhigt den Träger und macht ihn freundlich.'] => ['Der beruhigende Kliklak dieser Glocke beruhigt den Träger und macht ihn freundlich.', 'Der beruhigende Klang dieser Glocke macht den Träger zutraulicher.'],
    [8, 'Die geheime Spezialität des Alten Châteaus. Einmal verwendbar, um alle Statusprobleme eines Pokémon zu heilen.'] => ['Die geheime Spezialität des Alten Châteaus. Einmal verwendbar, um alle Statusprobleme eines Pokémon zu heilen.', 'Spezialität der Alten Villa. Heilt einmalig alle Statusprobleme eines Pokémon.'],
    [8, 'Diese neugierigen Brillen erhöhen die Spezial-Angriffskraft, erlauben aber nur den Einsatz eines einzigen Moves.'] => ['Diese neugierigen Brillen erhöhen die Spezial-Angriffskraft, erlauben aber nur den Einsatz eines einzigen Moves.', 'Erhöht den Spezial-Angriff des Trägers, legt ihn aber auf die erste gewählte Attacke fest.'],
    [8, 'Dieser scharf gekrümmte Krallen erhöht die Krit-Trefferquote des Besitzers.'] => ['Dieser scharf gekrümmte Krallen erhöht die Krit-Trefferquote des Besitzers.', 'Diese scharf gekrümmte Kralle erhöht die Volltrefferquote des Trägers.'],
    [8, 'Dieses Item erhöht die Spezial-Angriff-Werte eines Pokémon um eine Stufe, wenn es eine Ton-Attacke einsetzt.'] => ['Dieses Item erhöht die Spezial-Angriff-Werte eines Pokémon um eine Stufe, wenn es eine Ton-Attacke einsetzt.', 'Erhöht den Spezial-Angriff des Trägers nach einer Lärm-Attacke um eine Stufe.'],
    [8, 'Dieses Item stellt die PP eines gewählten Moves eines Pokémon vollständig wieder her.'] => ['Dieses Item stellt die PP eines gewählten Moves eines Pokémon vollständig wieder her.', 'Stellt die AP einer ausgewählten Attacke eines Pokémon vollständig wieder her.'],
    [8, 'Dieses exotisch duftende Räucherwerk lässt den Träger aufgebläht und langsam werden.'] => ['Dieses exotisch duftende Räucherwerk lässt den Träger aufgebläht und langsam werden.', 'Dieses exotisch duftende Räucherwerk lässt den Träger meist zuletzt angreifen.'],
    [8, 'Dieses neugierige Halstuch erhöht die Initiative, erlaubt aber nur den Einsatz eines einzigen Zugs.'] => ['Dieses neugierige Halstuch erhöht die Initiative, erlaubt aber nur den Einsatz eines einzigen Zugs.', 'Erhöht die Initiative des Trägers, legt ihn aber auf die erste gewählte Attacke fest.'],
    [8, 'Dieses neugierige Stirnband erhöht den Angriff, erlaubt aber nur den Einsatz eines einzigen Moves.'] => ['Dieses neugierige Stirnband erhöht den Angriff, erlaubt aber nur den Einsatz eines einzigen Moves.', 'Erhöht den Angriff des Trägers, legt ihn aber auf die erste gewählte Attacke fest.'],
    [8, 'Ein Einweg-Samen, der seinen Träger in Synthesefeldern stärkt.'] => ['Ein Einweg-Samen, der seinen Träger in Synthesefeldern stärkt.', 'Ein einmal verwendbarer Samen, der seinen Träger in Synthesefeldern stärkt.'],
    [8, 'Ein Fläschchen und Sammelgerät zum Aufnehmen und Verteilen von Sporen.'] => ['Ein Fläschchen und Sammelgerät zum Aufnehmen und Verteilen von Sporen.', 'Ein Fläschchen mit Sammelvorrichtung, um Sporen aufzunehmen und zu verteilen.'],
    [8, 'Ein Fossil von einem urzeitlichen Pokémon, das einst im Meer lebte. Es könnte eine Schale oder ein Panzer sein.'] => ['Ein Fossil von einem urzeitlichen Pokémon, das einst im Meer lebte. Es könnte eine Schale oder ein Panzer sein.', 'Fossil eines urzeitlichen Meeres-Pokémon. Es ähnelt einer Schale oder einem Panzer.'],
    [8, 'Ein Fragment pechschwarzer Energie.'] => ['Ein Fragment pechschwarzer Energie.', 'Ein Fragment tiefschwarzer Materie.'],
    [8, 'Ein Item für Pokémon. Es erhöht leicht den Basis-Wert der Spezial-Attacke eines einzelnen Pokémon.'] => ['Ein Item für Pokémon. Es erhöht leicht den Basis-Wert der Spezial-Attacke eines einzelnen Pokémon.', 'Erhöht die Spezial-Angriffs-EVs eines Pokémon leicht.'],
    [8, 'Ein Item zum Tragen. Eine Polarität zieht gleiche Pokémon an, die andere ermöglicht schnelles Entkommen.'] => ['Ein Item zum Tragen. Eine Polarität zieht gleiche Pokémon an, die andere ermöglicht schnelles Entkommen.', 'Ein Item zum Tragen. Eine Polung lockt Pokémon derselben Art wie den Träger an; die andere erleichtert die Flucht.'],
    [8, 'Ein Item, das Farfetch’d tragen kann. Dieser lange, steife Lauchstiel erhöht seine Krit-Trefferchance.'] => ['Ein Item, das Farfetch’d tragen kann. Dieser lange, steife Lauchstiel erhöht seine Krit-Trefferchance.', 'Ein Item für Porenta zum Tragen. Dieser lange, steife Lauchstiel erhöht seine Volltrefferquote.'],
    [8, 'Ein Item, das an ein Pokémon gegeben wird. Es erhöht leicht den Basis-Wert der Initiative eines einzelnen Pokémon.'] => ['Ein Item, das an ein Pokémon gegeben wird. Es erhöht leicht den Basis-Wert der Initiative eines einzelnen Pokémon.', 'Erhöht die Initiative-EVs eines Pokémon leicht.'],
    [8, 'Ein Item, das an ein Pokémon gegeben wird. Es erhöht leicht die Basis-HP eines einzelnen Pokémon.'] => ['Ein Item, das an ein Pokémon gegeben wird. Es erhöht leicht die Basis-HP eines einzelnen Pokémon.', 'Erhöht die KP-EVs eines Pokémon leicht.'],
    [8, 'Ein Item, das die maximale AP aller Attacken des Ziel-Pokémon optimal erhöht.'] => ['Ein Item, das die maximale AP aller Attacken des Ziel-Pokémon optimal erhöht.', 'Erhöht die maximalen AP aller Attacken eines Pokémon auf den höchstmöglichen Wert.'],
    [8, 'Ein Item, das die maximale PP eines einzelnen Moves des Ziel-Pokémon leicht erhöht.'] => ['Ein Item, das die maximale PP eines einzelnen Moves des Ziel-Pokémon leicht erhöht.', 'Erhöht die maximalen AP einer Attacke eines Pokémon leicht.'],
    [8, 'Ein Item, das die maximale PP eines einzelnen, vom Ziel-Pokémon erlernten Moves optimal erhöht.'] => ['Ein Item, das die maximale PP eines einzelnen, vom Ziel-Pokémon erlernten Moves optimal erhöht.', 'Erhöht die maximalen AP einer Attacke eines Pokémon auf den höchstmöglichen Wert.'],
    [8, 'Ein Item, das für 200 Schritte verhindert, dass wilde Pokémon auf niedrigem Level plötzlich erscheinen.'] => ['Ein Item, das für 200 Schritte verhindert, dass wilde Pokémon auf niedrigem Level plötzlich erscheinen.', 'Ein Item, das wilde Pokémon auf niedrigem Level 200 Schritte lang fernhält.'],
    [8, 'Ein Item, das für 500 Schritte verhindert, dass wilde Pokémon niedrigen Levels plötzlich auftauchen.'] => ['Ein Item, das für 500 Schritte verhindert, dass wilde Pokémon niedrigen Levels plötzlich auftauchen.', 'Ein Item, das wilde Pokémon auf niedrigem Level 500 Schritte lang fernhält.'],
    [8, 'Ein Item, das man bei einem Pokémon einsetzt. Es erhöht leicht den Basis-Angriff eines einzelnen Pokémon.'] => ['Ein Item, das man bei einem Pokémon einsetzt. Es erhöht leicht den Basis-Angriff eines einzelnen Pokémon.', 'Erhöht die Angriffs-EVs eines Pokémon leicht.'],
    [8, 'Ein Item, das verhindert, dass wilde Pokémon auf niedriger Stufe für 400 Schritte plötzlich auftauchen.'] => ['Ein Item, das verhindert, dass wilde Pokémon auf niedriger Stufe für 400 Schritte plötzlich auftauchen.', 'Ein Item, das wilde Pokémon auf niedrigem Level 400 Schritte lang fernhält.'],
    [8, 'Ein Juwel mit der Essenz der Dunkelheit. Wird gehalten, verstärkt es einmal die Kraft eines Unlicht-Angriffs.'] => ['Ein Juwel mit der Essenz der Dunkelheit. Wird gehalten, verstärkt es einmal die Kraft eines Unlicht-Angriffs.', 'Ein Juwel mit der Essenz der Dunkelheit. Verstärkt einmalig eine Unlicht-Attacke des Trägers.'],
    [8, 'Ein Meteorit voller Astralenergie. Nutze ihn, um Sonnfel und Lunastein in beliebiger Kombination zu verschmelzen.'] => ['Ein Meteorit voller Astralenergie. Nutze ihn, um Sonnfel und Lunastein in beliebiger Kombination zu verschmelzen.', 'Ein Meteorit voller Astralenergie. Wird er auf Sonnfel angewendet, kann es sich mit Lunastein vereinigen.'],
    [8, 'Ein Paar besonders robuste Brille für wissenschaftliche Forschung.'] => ['Ein Paar besonders robuste Brille für wissenschaftliche Forschung.', 'Eine besonders robuste Brille für die wissenschaftliche Forschung.'],
    [8, 'Ein Schlüssel zu den Kundenakten im Waisenhaus des Lapislazuli-Bezirks.'] => ['Ein Schlüssel zu den Kundenakten im Waisenhaus des Lapislazuli-Bezirks.', 'Ein Schlüssel zu den Kundenakten im Waisenhaus des Bezirks Lapis.'],
    [8, 'Ein Schlüssel, um das Waisenhaus und die Psychiatrie im Lapis-Bezirk zu öffnen.'] => ['Ein Schlüssel, um das Waisenhaus und die Psychiatrie im Lapis-Bezirk zu öffnen.', 'Ein Schlüssel für das Waisenhaus und die psychiatrische Klinik im Bezirk Lapis.'],
    [8, 'Ein Team Meteor Hundemarke. Der Name darauf: „Tara Copperman“.'] => ['Ein Team Meteor Hundemarke. Der Name darauf: „Tara Copperman“.', 'Hundemarke von Team Meteor. Als Name steht „Tara Copperman“ darauf.'],
    [8, 'Ein beliebter Snack in Lumiose City. Kann einmal benutzt werden, um alle Statusprobleme eines Pokémon zu heilen.'] => ['Ein beliebter Snack in Lumiose City. Kann einmal benutzt werden, um alle Statusprobleme eines Pokémon zu heilen.', 'Beliebter Snack aus Illumina City. Heilt einmalig alle Statusprobleme eines Pokémon.'],
    [8, 'Ein besonderer Stein, mit dem bestimmte Pokémon sich entwickeln können. Der Stein hat ein feuriges, orangenes Herz.'] => ['Ein besonderer Stein, mit dem bestimmte Pokémon sich entwickeln können. Der Stein hat ein feuriges, orangenes Herz.', 'Ein Stein mit feurigem, orangefarbenem Kern. Entwickelt bestimmte Pokémon.'],
    [8, 'Ein besonderer Stein, mit dem bestimmte Pokémon sich entwickeln können. Er trägt ein unverkennbares Blattmuster.'] => ['Ein besonderer Stein, mit dem bestimmte Pokémon sich entwickeln können. Er trägt ein unverkennbares Blattmuster.', 'Ein Stein mit unverkennbarem Blattmuster. Entwickelt bestimmte Pokémon.'],
    [8, 'Ein besonderer Stein, mit dem bestimmte Pokémon-Arten sich entwickeln können. Er funkelt wie ein glitzerndes Auge.'] => ['Ein besonderer Stein, mit dem bestimmte Pokémon-Arten sich entwickeln können. Er funkelt wie ein glitzerndes Auge.', 'Ein besonderer Stein, mit dem sich bestimmte Pokémon entwickeln können. Er funkelt wie ein Auge.'],
    [8, 'Ein besonderer Stein, mit dem bestimmte Pokémon-Arten sich entwickeln können. Er strahlt ein blendendes Licht aus.'] => ['Ein besonderer Stein, mit dem bestimmte Pokémon-Arten sich entwickeln können. Er strahlt ein blendendes Licht aus.', 'Ein Stein, der blendendes Licht ausstrahlt. Entwickelt bestimmte Pokémon.'],
    [8, 'Ein eigenartiger Stein, der bestimmte Pokémon-Arten entwickeln kann. Er ist blau wie ein klarer Wasserteich.'] => ['Ein eigenartiger Stein, der bestimmte Pokémon-Arten entwickeln kann. Er ist blau wie ein klarer Wasserteich.', 'Ein blauer Stein, der an einen Teich erinnert. Entwickelt bestimmte Pokémon.'],
    [8, 'Ein eigenartiges Metall, das bestimmte Pokémon-Arten zur Entwicklung bringt. Es besteht aus vielen Schichten.'] => ['Ein eigenartiges Metall, das bestimmte Pokémon-Arten zur Entwicklung bringt. Es besteht aus vielen Schichten.', 'Ein eigenartiges Metall aus vielen Schichten. Es entwickelt Duraludon zu Briduradon.'],
    [8, 'Ein eleganter, samtroter Umhang mit königlichem Pelzbesatz. Bei vollen KP steigt die Stärke von Attacken um 25 %.'] => ['Ein eleganter, samtroter Umhang mit königlichem Pelzbesatz. Bei vollen KP steigt die Stärke von Attacken um 25 %.', 'Ein samtroter Königsumhang. Bei vollen KP sind die Attacken des Trägers 25 % stärker.'],
    [8, 'Ein extrem seltenes und begehrtes Leckerli! Iss es, bevor es schmilzt, um 200 KP zu heilen!'] => ['Ein extrem seltenes und begehrtes Leckerli! Iss es, bevor es schmilzt, um 200 KP zu heilen!', 'Ein extrem seltenes und begehrtes Leckerli! Iss es, bevor es schmilzt, und stelle 200 KP wieder her.'],
    [8, 'Ein glasiger schwarzer Stein, der beim Spalten eine scharfe Schneide bildet. Ein bestimmtes Pokémon liebt ihn sehr.'] => ['Ein glasiger schwarzer Stein, der beim Spalten eine scharfe Schneide bildet. Ein bestimmtes Pokémon liebt ihn sehr.', 'Ein glasiger, schwarzer Stein, der beim Spalten eine scharfe Schneide bildet. Er entwickelt Sichlor zu Axantor.'],
    [8, 'Ein hell leuchtender Ball, den Dialga tragen kann. Er verstärkt Drachen- und Stahl-Attacken, wenn er gehalten wird.'] => ['Ein hell leuchtender Ball, den Dialga tragen kann. Er verstärkt Drachen- und Stahl-Attacken, wenn er gehalten wird.', 'Ein hell leuchtender Orb. Verstärkt Dialgas Drachen- und Stahl-Attacken, wenn es ihn trägt.'],
    [8, 'Ein kleiner blauer Splitter. Es scheint ein Fragment eines alten Werkzeugs zu sein.'] => ['Ein kleiner blauer Splitter. Es scheint ein Fragment eines alten Werkzeugs zu sein.', 'Ein kleiner blauer Splitter. Er scheint ein Fragment eines alten Werkzeugs zu sein.'],
    [8, 'Ein kleiner roter Splitter. Es scheint ein Fragment eines Werkzeugs aus längst vergangener Zeit zu sein.'] => ['Ein kleiner roter Splitter. Es scheint ein Fragment eines Werkzeugs aus längst vergangener Zeit zu sein.', 'Ein kleiner roter Splitter. Er scheint ein Fragment eines Werkzeugs aus längst vergangener Zeit zu sein.'],
    [8, 'Ein leeres Briefpapier ohne erkennbaren Zweck. Wenn du es zu lange ansiehst, scheint es dir zuzuzwinkern.'] => ['Ein leeres Briefpapier ohne erkennbaren Zweck. Wenn du es zu lange ansiehst, scheint es dir zuzuzwinkern.', 'Leeres Briefpapier ohne erkennbaren Zweck. Bei längerem Hinsehen scheint es zuzuzwinkern.'],
    [8, 'Ein leuchtender Ball, den Giratina trägt. Er verstärkt Drachen- und Geist-Attacken, wenn er getragen wird.'] => ['Ein leuchtender Ball, den Giratina trägt. Er verstärkt Drachen- und Geist-Attacken, wenn er getragen wird.', 'Ein leuchtender Orb. Verstärkt Giratinas Drachen- und Geist-Attacken, wenn es ihn trägt.'],
    [8, 'Ein nahrhaftes Getränk für Pokémon. Erhöht beim Trinken den Basis-Angriff eines einzelnen Pokémon.'] => ['Ein nahrhaftes Getränk für Pokémon. Erhöht beim Trinken den Basis-Angriff eines einzelnen Pokémon.', 'Erhöht die Angriffs-EVs eines Pokémon.'],
    [8, 'Ein nahrhaftes Getränk für Pokémon. Erhöht nach dem Trinken den Basis-Wert Initiative eines einzelnen Pokémon.'] => ['Ein nahrhaftes Getränk für Pokémon. Erhöht nach dem Trinken den Basis-Wert Initiative eines einzelnen Pokémon.', 'Erhöht die Initiative-EVs eines Pokémon.'],
    [8, 'Ein nahrhaftes Getränk für Pokémon. Es erhöht die Basis-HP eines einzelnen Pokémon, wenn es getrunken wird.'] => ['Ein nahrhaftes Getränk für Pokémon. Es erhöht die Basis-HP eines einzelnen Pokémon, wenn es getrunken wird.', 'Erhöht die KP-EVs eines Pokémon.'],
    [8, 'Ein sehr bitteres Heilpulver. Es kann einmal benutzt werden, um alle Statusprobleme eines Pokémon zu heilen.'] => ['Ein sehr bitteres Heilpulver. Es kann einmal benutzt werden, um alle Statusprobleme eines Pokémon zu heilen.', 'Sehr bitteres Heilpulver. Heilt einmalig alle Statusprobleme eines Pokémon.'],
    [8, 'Ein sehr leckerer Schwanz von etwas. Kann in Läden zu einem hohen Preis verkauft werden.'] => ['Ein sehr leckerer Schwanz von etwas. Kann in Läden zu einem hohen Preis verkauft werden.', 'Ein köstlich aussehender Schwanz von Flegmon. Er lässt sich in Geschäften für viel Geld verkaufen.'],
    [8, 'Ein seltsamer Stein, der bestimmte Pokémon zur Entwicklung bringt. Er birgt Schatten, so dunkel wie die Nacht.'] => ['Ein seltsamer Stein, der bestimmte Pokémon zur Entwicklung bringt. Er birgt Schatten, so dunkel wie die Nacht.', 'Ein Stein voller nachtschwarzer Schatten. Entwickelt bestimmte Pokémon.'],
    [8, 'Ein seltsamer Stein, mit dem bestimmte Pokémon-Arten sich entwickeln können. Er glüht rot wie die Abendsonne.'] => ['Ein seltsamer Stein, mit dem bestimmte Pokémon-Arten sich entwickeln können. Er glüht rot wie die Abendsonne.', 'Ein Stein, rot glühend wie die Abendsonne. Entwickelt bestimmte Pokémon.'],
    [8, 'Ein spezielles Programm, das das Pokémon seine Verteidigungs-Training vergessen lässt.'] => ['Ein spezielles Programm, das das Pokémon seine Verteidigungs-Training vergessen lässt.', 'Setzt die Verteidigungs-EVs eines Pokémon zurück. Wiederverwendbar.'],
    [8, 'Ein spezielles, wiederverwendbares Programm, das das Pokémon alle Trainingswerte vergessen lässt.'] => ['Ein spezielles, wiederverwendbares Programm, das das Pokémon alle Trainingswerte vergessen lässt.', 'Ein spezielles, wiederverwendbares Programm, mit dem ein Pokémon alle seine EVs zurücksetzt.'],
    [8, 'Ein süß-scharfes Bonbon. Es taut ein eingefrorenes Pokémon auf.'] => ['Ein süß-scharfes Bonbon. Es taut ein eingefrorenes Pokémon auf.', 'Ein süß-scharfes Zimtbonbon. Es taut ein eingefrorenes Pokémon auf.'],
    [8, 'Ein süßer Trank mit Zuckerkugeln verziert. Stellt beim Trinken bis zu 180 KP eines verletzten Pokémon wieder her.'] => ['Ein süßer Trank mit Zuckerkugeln verziert. Stellt beim Trinken bis zu 180 KP eines verletzten Pokémon wieder her.', 'Ein süßes Getränk mit Zuckerkugeln. Beim Trinken stellt es bis zu 180 KP eines verletzten Pokémon wieder her.'],
    [8, 'Ein süßer, sprudelnder Bonbon. Weckt ein Pokémon blitzschnell auf.'] => ['Ein süßer, sprudelnder Bonbon. Weckt ein Pokémon blitzschnell auf.', 'Ein süßes, prickelndes Bonbon. Es weckt ein Pokémon sofort auf.'],
    [8, 'Ein süßer, zäher Bonbon. Lindert Verbrennungen bei Pokémon.'] => ['Ein süßer, zäher Bonbon. Lindert Verbrennungen bei Pokémon.', 'Ein süßes, zähes Salzwasser-Toffee. Es heilt ein Pokémon von Verbrennungen.'],
    [8, 'Ein süßes, minzig-frisches Bonbon. Es heilt ein Pokémon von Gift.'] => ['Ein süßes, minzig-frisches Bonbon. Es heilt ein Pokémon von Gift.', 'Ein süßes Pfefferminzbonbon. Es heilt ein Pokémon von Vergiftung.'],
    [8, 'Ein verlorener, gewöhnlicher Dunkelschlüssel. Ein bisschen Sprühfarbe ist darauf.'] => ['Ein verlorener, gewöhnlicher Dunkelschlüssel. Ein bisschen Sprühfarbe ist darauf.', 'Ein verlorener, gewöhnlicher Schlüssel in dunkler Farbe. Ein bisschen Sprühfarbe ist darauf.'],
    [8, 'Ein wiederverwendbares Spezialprogramm, das das Pokémon seine Attacken-Training vergessen lässt.'] => ['Ein wiederverwendbares Spezialprogramm, das das Pokémon seine Attacken-Training vergessen lässt.', 'Setzt die Angriffs-EVs eines Pokémon zurück. Wiederverwendbar.'],
    [8, 'Eine Erdbeer-Leckerei! Iss sie, bevor sie schmilzt, um 90 KP zu heilen!'] => ['Eine Erdbeer-Leckerei! Iss sie, bevor sie schmilzt, um 90 KP zu heilen!', 'Eine fruchtige Eiscreme! Iss sie, bevor sie schmilzt, und stelle 90 KP wieder her.'],
    [8, 'Eine Schlüsselkarte von einem ranghohen Team Meteor-Offizier. Damit lassen sich gesperrte Bereiche öffnen.'] => ['Eine Schlüsselkarte von einem ranghohen Team Meteor-Offizier. Damit lassen sich gesperrte Bereiche öffnen.', 'Karte eines hohen Team-Meteor-Offiziers. Öffnet gesperrte Bereiche.'],
    [8, 'Eine geheimnisvolle Schuppe, die ein bestimmtes Pokémon zur Entwicklung bringt. Sie glänzt in Regenbogenfarben.'] => ['Eine geheimnisvolle Schuppe, die ein bestimmtes Pokémon zur Entwicklung bringt. Sie glänzt in Regenbogenfarben.', 'Eine geheimnisvolle Schuppe, die in Regenbogenfarben glänzt. Mit ihr kann sich Barschwa zu Milotic entwickeln.'],
    [8, 'Eine hübsche, herzförmige Schuppe, die extrem selten ist. Manche Trainer freuen sich sehr, eine zu bekommen.'] => ['Eine hübsche, herzförmige Schuppe, die extrem selten ist. Manche Trainer freuen sich sehr, eine zu bekommen.', 'Seltene, herzförmige Schuppe. Bezahlung zum Wiedererlernen vergessener Attacken.'],
    [8, 'Eine praktische Karte, die du jederzeit ansehen kannst. Sie zeigt dir sogar deinen aktuellen Standort in der Region.'] => ['Eine praktische Karte, die du jederzeit ansehen kannst. Sie zeigt dir sogar deinen aktuellen Standort in der Region.', 'Eine jederzeit abrufbare Karte der Region. Zeigt auch deinen aktuellen Standort.'],
    [8, 'Eine verwitterte und brüchige Karte. In einer zerfallenen Höhle mit unzähligen Statuen ist eine Truhe eingezeichnet.'] => ['Eine verwitterte und brüchige Karte. In einer zerfallenen Höhle mit unzähligen Statuen ist eine Truhe eingezeichnet.', 'Brüchige, alte Karte. Zeigt eine Truhe in einer zerfallenen Höhle voller Statuen.'],
