    [8, 'Ermöglicht Wulaosu die Mega-Entwicklung im Kampf.'] => ['Ermöglicht Wulaosu die Mega-Entwicklung im Kampf.', 'Ein Mega-Stein. Wenn Wulaosu ihn trägt, kann es im Kampf gigadynamaximieren.'],
    [8, 'Es erhöht den Spezial-Angriff, wenn es von einer Wasser-Attacke getroffen wird. Es kann nur einmal benutzt werden.'] => ['Es erhöht den Spezial-Angriff, wenn es von einer Wasser-Attacke getroffen wird. Es kann nur einmal benutzt werden.', 'Erhöht den Spezial-Angriff des Trägers, wenn ihn eine Wasser-Attacke trifft. Einmalig.'],
    [8, 'Es ist enorm schwer und lässt den Träger langsamer als sonst bewegen.'] => ['Es ist enorm schwer und lässt den Träger langsamer als sonst bewegen.', 'Der Träger führt seine Attacke meist zuletzt aus.'],
    [8, 'Es stellt eine gesenkte Statuswert im Kampf wieder her. Es kann nur einmal benutzt werden.'] => ['Es stellt eine gesenkte Statuswert im Kampf wieder her. Es kann nur einmal benutzt werden.', 'Stellt im Kampf gesenkte Statuswerte wieder her. Kann nur einmal benutzt werden.'],
    [8, 'Es stellt vergifteten Pokémon nach und nach KP wieder her. Bei anderen Typen fügt es Schaden zu.'] => ['Es stellt vergifteten Pokémon nach und nach KP wieder her. Bei anderen Typen fügt es Schaden zu.', 'Gift-Pokémon erhalten durch dieses Item nach und nach KP zurück. Allen anderen Pokémon fügt es Schaden zu.'],
    [8, 'Es verlängert die Dauer von Hagel, wenn der Träger es benutzt.'] => ['Es verlängert die Dauer von Hagel, wenn der Träger es benutzt.', 'Verlängert Hagel, wenn der Träger die Attacke einsetzt.'],
